ALTER TABLE public.satellite_raster_assets ADD CONSTRAINT satellite_verified_proof_required CHECK (verified_at IS NULL OR COALESCE(byte_size>0 AND content_sha256 ~ '^[a-f0-9]{64}$' AND jsonb_typeof(provenance)='object' AND provenance->>'schema_version'='1',false));
CREATE OR REPLACE FUNCTION public.satellite_finish_work(p_id uuid,p_token uuid,p_status text,p_result jsonb DEFAULT NULL,p_error text DEFAULT NULL,p_retry_ms integer DEFAULT 30000) RETURNS boolean LANGUAGE plpgsql SET search_path=public AS $$ DECLARE changed integer; BEGIN IF p_status NOT IN ('verified','retry','dead','cancelled') THEN RAISE EXCEPTION 'Invalid terminal status'; END IF; IF p_status='verified' AND NOT COALESCE(jsonb_typeof(p_result)='object' AND p_result->>'schema_version'='1' AND p_result->>'verified'='true' AND p_result->>'boundary_hash' IS NOT NULL AND p_result->>'acquisition_id' IS NOT NULL AND p_result->>'layer' IS NOT NULL,false) THEN RAISE EXCEPTION 'Missing verification proof'; END IF; UPDATE public.satellite_work_items w SET status=CASE WHEN p_status='retry' AND attempts>=5 THEN 'dead' ELSE p_status END,output_manifest=p_result,last_error=left(p_error,500),due_at=now()+make_interval(secs=>greatest(1,least(p_retry_ms,86400000))/1000.0),verified_at=CASE WHEN p_status='verified' THEN now() ELSE NULL END,lease_token=NULL,lease_expires_at=NULL WHERE w.id=p_id AND w.status='leased' AND w.lease_token=p_token AND w.lease_expires_at>now() AND (p_status<>'verified' OR COALESCE(p_result->>'boundary_hash'=w.boundary_hash AND p_result->>'acquisition_id'=w.acquisition_id::text AND p_result->>'layer'=w.layer,false)); GET DIAGNOSTICS changed=ROW_COUNT; RETURN changed=1; END $$;
REVOKE ALL ON FUNCTION public.satellite_finish_work(uuid,uuid,text,jsonb,text,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.satellite_finish_work(uuid,uuid,text,jsonb,text,integer) TO service_role;